CREATE TABLE [Experiences] ([Id] int NOT NULL IDENTITY, [Type] nvarchar(max) NOT NULL, [Title] nvarchar(max) NOT NULL, [DateRange] nvarchar(max) NOT NULL, [CompanyOrInstitution] nvarchar(max) NOT NULL, [Description] nvarchar(max) NOT NULL, [CreatedDate] datetime2 NOT NULL, CONSTRAINT [PK_Experiences] PRIMARY KEY ([Id])); CREATE TABLE [Projects] ([Id] int NOT NULL IDENTITY, [Name] nvarchar(max) NOT NULL, [Description] nvarchar(max) NOT NULL, [Link] nvarchar(max) NOT NULL, [Icon] nvarchar(max) NOT NULL, [TechTags] nvarchar(max) NOT NULL, [DisplayOrder] int NOT NULL, [CreatedDate] datetime2 NOT NULL, CONSTRAINT [PK_Projects] PRIMARY KEY ([Id]));
